\version "2.27.2"
% automatically converted by musicxml2ly from 02e-Rests-NoType.xml
\pointAndClickOff

\header {
  texidoc = "In some cases, a <rest> element misses the <type> child (this
    happens, for example, with voices in Finale, where you don't manually insert
    a rest).

    The second note in voice 2 misses a <staff> element; it is thus positioned
    in the upper staff."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \clef "treble" \time 4/4 \key c \major \partial 4 c4 a1 \bar "|."
}

PartPOneVoiceTwo = \relative e {
  \clef "bass" \time 4/4 \key c \major \partial 4 r4 \change Staff="1" e1
  \change Staff="2" \bar "|."
}


% The score definition
\score {
  <<
    \new PianoStaff = "P1" <<
      \context Staff = "1" <<
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
      \context Staff = "2" <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceTwo" {
          \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
